text:
Here's your water tracker: tap + for each glass, and it resets each day with a goal of 8.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Segoe UI, sans-serif; margin: 0; padding: 24px; text-align: center; background: #f3f8fb; color: #1b3a4b; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  #date { font-size: 13px; color: #5f7d8c; margin-bottom: 16px; }
  #count { font-size: 56px; font-weight: 600; }
  #msg { height: 22px; margin: 4px 0 16px; font-size: 14px; }
  #glasses { display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; margin-bottom: 20px; }
  .g { width: 34px; height: 46px; border: 2px solid #4a9fc8; border-radius: 4px 4px 10px 10px; background: #fff; }
  .g.full { background: #4a9fc8; }
  button { font-size: 18px; padding: 10px 22px; margin: 0 4px; border: 0; border-radius: 8px; background: #4a9fc8; color: #fff; cursor: pointer; }
  button.alt { background: #d5e4ec; color: #1b3a4b; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="glasses"></div>
  <button onclick="change(1)">+ Glass</button>
  <button class="alt" onclick="change(-1)">- Glass</button>
  <button class="alt" onclick="reset()">Reset</button>
<script>
  var GOAL = 8;
  var today = new Date().toDateString();
  var n = 0;
  try {
    var saved = JSON.parse(localStorage.getItem("water") || "{}");
    if (saved.day === today) n = saved.n || 0;
  } catch (e) {}
  function save() {
    try { localStorage.setItem("water", JSON.stringify({ day: today, n: n })); } catch (e) {}
  }
  function change(d) { n = Math.max(0, n + d); save(); draw(); }
  function reset() { n = 0; save(); draw(); }
  function draw() {
    document.getElementById("date").textContent = today;
    document.getElementById("count").textContent = n + " / " + GOAL;
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < Math.max(GOAL, n); i++) {
      var g = document.createElement("div");
      g.className = "g" + (i < n ? " full" : "");
      box.appendChild(g);
    }
    var m = n >= GOAL ? "Goal reached. Well done! 💧" : (GOAL - n) + " more to go";
    document.getElementById("msg").textContent = m;
  }
  draw();
</script>
</body>
</html>
```

If your screen doesn't keep the count after closing, it will start again from 0.
